"""Strict CSV record conversion library and command-line tool."""

import csv
import io
import json
import sys
from typing import Iterable, Mapping


_HEADER = ["name", "note"]
_KEYS = frozenset(_HEADER)


def _validate_quoting(text: str) -> None:
    """Reject quote placement that csv.reader otherwise accepts permissively."""
    field_start = True
    in_quotes = False
    after_quote = False
    index = 0

    while index < len(text):
        char = text[index]

        if in_quotes:
            if after_quote:
                if char == '"':
                    after_quote = False
                elif char == ',':
                    in_quotes = False
                    after_quote = False
                    field_start = True
                elif char == '\r' or char == '\n':
                    in_quotes = False
                    after_quote = False
                    field_start = True
                    if char == '\r' and index + 1 < len(text) and text[index + 1] == '\n':
                        index += 1
                else:
                    raise ValueError(
                        "malformed CSV: unexpected character after closing quote"
                    )
            elif char == '"':
                after_quote = True
        else:
            if char == '"':
                if not field_start:
                    raise ValueError(
                        "malformed CSV: quote inside an unquoted field"
                    )
                in_quotes = True
                after_quote = False
                field_start = False
            elif char == ',':
                field_start = True
            elif char == '\r' or char == '\n':
                field_start = True
                if char == '\r' and index + 1 < len(text) and text[index + 1] == '\n':
                    index += 1
            else:
                field_start = False

        index += 1

    if in_quotes and not after_quote:
        raise ValueError("malformed CSV: unterminated quoted field")


def parse_records(text: str) -> list[dict[str, str]]:
    """Parse CSV having exactly the header ``name,note``."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    _validate_quoting(text)
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("missing CSV header; expected name,note") from None
    except csv.Error as exc:
        raise ValueError(f"malformed CSV header: {exc}") from None

    if header != _HEADER:
        raise ValueError("wrong CSV header; expected name,note")

    records: list[dict[str, str]] = []
    try:
        for row_number, row in enumerate(reader, start=2):
            if len(row) != 2:
                raise ValueError(
                    f"wrong column count on row {row_number}: expected 2, got {len(row)}"
                )
            records.append({"name": row[0], "note": row[1]})
    except csv.Error as exc:
        raise ValueError(f"malformed CSV: {exc}") from None

    return records


def format_records(records: Iterable[Mapping[str, str]]) -> str:
    """Serialize validated name/note records using LF line terminators."""
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)

    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError("records must be an iterable of mappings") from None

    for record_number, record in enumerate(iterator, start=1):
        if not isinstance(record, Mapping):
            raise ValueError(f"record {record_number} must be a mapping")
        try:
            keys = frozenset(record.keys())
        except (AttributeError, TypeError):
            raise ValueError(
                f"record {record_number} must have exactly name and note keys"
            ) from None
        if keys != _KEYS or len(record) != 2:
            raise ValueError(
                f"record {record_number} must have exactly name and note keys"
            )

        name = record["name"]
        note = record["note"]
        if not isinstance(name, str) or not isinstance(note, str):
            raise ValueError(
                f"record {record_number} name and note values must be strings"
            )
        writer.writerow([name, note])

    return output.getvalue()


def to_json(text: str) -> str:
    """Convert valid CSV text to JSON without changing field strings."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main() -> int:
    try:
        result = to_json(sys.stdin.read())
    except ValueError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 2

    sys.stdout.write(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import json
import subprocess
import sys
import unittest
from pathlib import Path

import csv_tool


class ParseRecordsTests(unittest.TestCase):
    def test_basic_records(self):
        self.assertEqual(
            csv_tool.parse_records("name,note\nAda,hello\nBob,world\n"),
            [{"name": "Ada", "note": "hello"}, {"name": "Bob", "note": "world"}],
        )

    def test_quoted_comma(self):
        self.assertEqual(
            csv_tool.parse_records('name,note\nAda,"hello, world"\n'),
            [{"name": "Ada", "note": "hello, world"}],
        )

    def test_doubled_quote(self):
        self.assertEqual(
            csv_tool.parse_records('name,note\nAda,"She said ""hi"""\n'),
            [{"name": "Ada", "note": 'She said "hi"'}],
        )

    def test_embedded_lf(self):
        self.assertEqual(
            csv_tool.parse_records('name,note\nAda,"line 1\nline 2"\n'),
            [{"name": "Ada", "note": "line 1\nline 2"}],
        )

    def test_crlf_records_and_embedded_crlf(self):
        self.assertEqual(
            csv_tool.parse_records('name,note\r\nAda,"line 1\r\nline 2"\r\nBob,ok\r\n'),
            [
                {"name": "Ada", "note": "line 1\r\nline 2"},
                {"name": "Bob", "note": "ok"},
            ],
        )

    def test_unicode(self):
        self.assertEqual(
            csv_tool.parse_records("name,note\nZoë,雪だるま ☃\n"),
            [{"name": "Zoë", "note": "雪だるま ☃"}],
        )

    def test_empty_fields(self):
        self.assertEqual(
            csv_tool.parse_records("name,note\n,\nAda,\n,note\n"),
            [
                {"name": "", "note": ""},
                {"name": "Ada", "note": ""},
                {"name": "", "note": "note"},
            ],
        )

    def test_missing_header(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("")

    def test_wrong_header(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("note,name\nhello,Ada\n")

    def test_extra_header_column(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("name,note,other\nAda,hello,x\n")

    def test_unclosed_quote(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records('name,note\nAda,"unfinished\n')

    def test_too_many_columns(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("name,note\nAda,hello,extra\n")

    def test_too_few_columns(self):
        with self.assertRaises(ValueError):
            csv_tool.parse_records("name,note\nAda\n")


class FormatRecordsTests(unittest.TestCase):
    def test_basic_output_and_lf_terminators(self):
        self.assertEqual(
            csv_tool.format_records([{"name": "Ada", "note": "hello"}]),
            "name,note\nAda,hello\n",
        )

    def test_quotes_comma(self):
        self.assertEqual(
            csv_tool.format_records([{"name": "Ada", "note": "hello, world"}]),
            'name,note\nAda,"hello, world"\n',
        )

    def test_doubles_quotes(self):
        self.assertEqual(
            csv_tool.format_records([{"name": "Ada", "note": 'say "hi"'}]),
            'name,note\nAda,"say ""hi"""\n',
        )

    def test_preserves_newlines_and_unicode(self):
        formatted = csv_tool.format_records([{"name": "Zoë", "note": "雪\r\nline 2"}])
        self.assertEqual(formatted, 'name,note\nZoë,"雪\r\nline 2"\n')
        self.assertEqual(
            csv_tool.parse_records(formatted),
            [{"name": "Zoë", "note": "雪\r\nline 2"}],
        )

    def test_empty_records_and_fields(self):
        self.assertEqual(csv_tool.format_records([]), "name,note\n")
        self.assertEqual(
            csv_tool.format_records([{"name": "", "note": ""}]),
            "name,note\n,\n",
        )

    def test_missing_key_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.format_records([{"name": "Ada"}])

    def test_extra_key_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.format_records([{"name": "Ada", "note": "hi", "extra": "x"}])

    def test_non_string_name_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.format_records([{"name": 7, "note": "hi"}])

    def test_non_string_note_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.format_records([{"name": "Ada", "note": None}])


class JsonTests(unittest.TestCase):
    def test_json_preserves_all_field_strings(self):
        source = 'name,note\n"A, B","line 1\nline 2 and ""quotes"""\nZoë,雪\n'
        result = csv_tool.to_json(source)
        self.assertEqual(
            json.loads(result),
            [
                {"name": "A, B", "note": 'line 1\nline 2 and "quotes"'},
                {"name": "Zoë", "note": "雪"},
            ],
        )
        self.assertIsInstance(result, str)

    def test_invalid_csv_is_rejected(self):
        with self.assertRaises(ValueError):
            csv_tool.to_json("bad,header\nx,y\n")


class CliTests(unittest.TestCase):
    @staticmethod
    def run_cli(source):
        return subprocess.run(
            [sys.executable, str(Path(csv_tool.__file__).resolve())],
            input=source,
            text=True,
            capture_output=True,
            check=False,
        )

    def test_success_stdout_only_and_exit_zero(self):
        proc = self.run_cli('name,note\nZoë,"hello, 雪"\n')
        self.assertEqual(proc.returncode, 0)
        self.assertEqual(proc.stderr, "")
        self.assertEqual(
            json.loads(proc.stdout),
            [{"name": "Zoë", "note": "hello, 雪"}],
        )

    def test_invalid_input_stderr_no_traceback_and_exit_two(self):
        proc = self.run_cli('name,note\nAda,"unfinished\n')
        self.assertEqual(proc.returncode, 2)
        self.assertEqual(proc.stdout, "")
        self.assertTrue(proc.stderr.strip())
        self.assertNotIn("Traceback", proc.stderr)


if __name__ == "__main__":
    unittest.main()

